import type { NavigationIR, RouteDefinition, RouteParamSchema } from '@expo-foundation/core';

export interface GeneratedNavigationFile {
  path: string;
  content: string;
  ownership: 'generated' | 'user-protected';
}

const GENERATED_HEADER = `/**
 * @generated by @expo-foundation/navigation
 * DO NOT EDIT MANUALLY — deterministic output from navigation.json via Canonical NavigationIR.
 */`;

function paramSchemaToTsType(schema: RouteParamSchema): string {
  switch (schema.type) {
    case 'number':
      return 'number';
    case 'boolean':
      return 'boolean';
    case 'enum':
      return schema.enumValues && schema.enumValues.length > 0
        ? schema.enumValues.map((v) => `'${v}'`).join(' | ')
        : 'string';
    case 'string':
    default:
      return 'string';
  }
}

export function generateRouteParamsTypeDefinitions(navIR: NavigationIR): string {
  const lines: string[] = [];
  lines.push('export interface RouteParameterMap {');
  for (const [routeId, paramMap] of Object.entries(navIR.routeParameters)) {
    const entries = Object.entries(paramMap);
    if (entries.length === 0) {
      lines.push(`  '${routeId}': Record<string, never>;`);
    } else {
      lines.push(`  '${routeId}': {`);
      for (const [paramKey, schema] of entries) {
        const optional = schema.required === false ? '?' : '';
        lines.push(`    ${paramKey}${optional}: ${paramSchemaToTsType(schema)};`);
      }
      lines.push('  };');
    }
  }
  lines.push('}');
  lines.push('export type RouteId = keyof RouteParameterMap;');
  return lines.join('\n');
}

function routeToAppFilePath(route: RouteDefinition): string {
  const isAuth =
    route.access === 'guest' ||
    route.id.startsWith('auth.') ||
    route.path.startsWith('/login') ||
    route.path.startsWith('/register') ||
    route.path.startsWith('/verify');
  const group = isAuth ? '(auth)' : '(application)';

  const clean = route.path
    .replace(/^\/+/, '')
    .replace(/\/+$/, '')
    .replace(/:([a-zA-Z0-9_]+)/g, '[$1]');

  if (!clean) {
    return `src/app/${group}/index.tsx`;
  }
  return `src/app/${group}/${clean}.tsx`;
}

export function generateNavigationFiles(navIR: NavigationIR): GeneratedNavigationFile[] {
  const files: GeneratedNavigationFile[] = [];

  // 1. src/foundation/config/navigation.generated.ts
  files.push({
    path: 'src/foundation/config/navigation.generated.ts',
    ownership: 'generated',
    content: `${GENERATED_HEADER}

export const NAVIGATION_CONFIG = ${JSON.stringify(
      {
        id: navIR.id,
        rootNavigatorId: navIR.rootNavigatorId,
        navigators: navIR.navigators,
        routes: navIR.routes,
        linking: navIR.linking,
        navigationPolicies: navIR.navigationPolicies,
        screenRefs: navIR.screenRefs,
      },
      null,
      2
    )} as const;

${generateRouteParamsTypeDefinitions(navIR)}
`,
  });

  // 2. src/foundation/navigation/RouteRegistry.ts
  files.push({
    path: 'src/foundation/navigation/RouteRegistry.ts',
    ownership: 'generated',
    content: `${GENERATED_HEADER}
import { NAVIGATION_CONFIG, type RouteId, type RouteParameterMap } from '../config/navigation.generated';

export class GeneratedRouteRegistry {
  readonly routes = NAVIGATION_CONFIG.routes;

  getRoute(routeId: RouteId) {
    return this.routes[routeId];
  }

  buildUrl<K extends RouteId>(routeId: K, params?: RouteParameterMap[K]): string {
    const route = this.routes[routeId];
    let url: string = route.path;
    if (params) {
      for (const [key, val] of Object.entries(params as Record<string, unknown>)) {
        url = url.replace(\`:\${key}\`, encodeURIComponent(String(val)));
      }
    }
    return url;
  }
}

export const routeRegistry = new GeneratedRouteRegistry();
`,
  });

  // 3. src/foundation/navigation/NavigationState.ts
  files.push({
    path: 'src/foundation/navigation/NavigationState.ts',
    ownership: 'generated',
    content: `${GENERATED_HEADER}
import type { RouteId } from '../config/navigation.generated';

export interface NavigationHistoryEntry {
  key: string;
  routeId: RouteId;
  params: Record<string, unknown>;
  timestamp: number;
}

export interface NavigationState {
  activeNavigatorId: string;
  activeRouteId: RouteId;
  params?: Record<string, unknown>;
  history: NavigationHistoryEntry[];
  selectedTab?: string;
  modalStack: string[];
}
`,
  });

  // 4. src/foundation/navigation/RouteResolver.ts
  files.push({
    path: 'src/foundation/navigation/RouteResolver.ts',
    ownership: 'generated',
    content: `${GENERATED_HEADER}
import React from 'react';
import { screenRegistry } from '../../screens/registry';

/**
 * Resolves an external screen reference from the ScreenRegistry.
 * Never generates visual layout or UI components inside the navigation layer.
 */
export function resolveScreenReference(screenRef: string): React.ComponentType<any> {
  const Component = screenRegistry.resolve(screenRef);
  if (!Component) {
    throw new Error(
      \`Unresolved screen reference "\${screenRef}". Register this screen ID in src/screens/registry.ts.\`
    );
  }
  return Component;
}
`,
  });

  // 5. src/foundation/navigation/DeepLinkManager.ts
  files.push({
    path: 'src/foundation/navigation/DeepLinkManager.ts',
    ownership: 'generated',
    content: `${GENERATED_HEADER}
import { NAVIGATION_CONFIG, type RouteId } from '../config/navigation.generated';

export class GeneratedDeepLinkManager {
  private intendedRouteId: RouteId | null = null;
  private intendedParams: Record<string, unknown> = {};

  readonly scheme = NAVIGATION_CONFIG.linking.scheme;
  readonly hosts = NAVIGATION_CONFIG.linking.hosts ?? [];

  setIntendedDestination(routeId: RouteId, params: Record<string, unknown> = {}): void {
    if (String(routeId).includes('://')) {
      throw new Error('Unsafe external redirect rejected.');
    }
    if (!(routeId in NAVIGATION_CONFIG.routes)) {
      throw new Error(\`Unknown internal routeId "\${String(routeId)}".\`);
    }
    this.intendedRouteId = routeId;
    this.intendedParams = params;
  }

  consumeIntendedDestination(): { routeId: RouteId; params: Record<string, unknown> } | null {
    if (!this.intendedRouteId) return null;
    const target = { routeId: this.intendedRouteId, params: this.intendedParams };
    this.intendedRouteId = null;
    this.intendedParams = {};
    return target;
  }
}

export const deepLinkManager = new GeneratedDeepLinkManager();
`,
  });

  // 6. iOS SwiftUI Renderers (Expo UI SDK 58 + createStandardRouterNavigator)
  files.push({
    path: 'src/foundation/navigation/renderers/ios/NativeStack.ios.tsx',
    ownership: 'generated',
    content: `${GENERATED_HEADER}
import React from 'react';
import { NavigationStack, NavigationDestination, Toolbar } from '@expo/ui/swift-ui';
import { createStandardRouterNavigator, integrateWithRouter } from 'expo-router';
import { resolveScreenReference } from '../../RouteResolver';

export interface IOSNativeStackProps {
  navigatorId: string;
  controlledPath: string[];
  onPathChange: (nextPath: string[]) => void;
  rootScreenRef: string;
  routeParams?: Record<string, unknown>;
}

export function IOSNativeStackRenderer(props: IOSNativeStackProps) {
  const RootScreen = resolveScreenReference(props.rootScreenRef);
  return (
    <NavigationStack path={props.controlledPath} onPathChange={props.onPathChange}>
      <Toolbar />
      <RootScreen {...(props.routeParams ?? {})} />
      <NavigationDestination />
    </NavigationStack>
  );
}

export const IOSRouterIntegratedStack = integrateWithRouter(
  createStandardRouterNavigator(IOSNativeStackRenderer)
);
`,
  });

  files.push({
    path: 'src/foundation/navigation/renderers/ios/NativeTabs.ios.tsx',
    ownership: 'generated',
    content: `${GENERATED_HEADER}
import React from 'react';
import { TabView } from '@expo/ui/swift-ui';
import { createStandardRouterNavigator, integrateWithRouter } from 'expo-router';

export interface IOSNativeTabsProps {
  selectedTab: string;
  onSelectTab: (tabId: string) => void;
  children?: React.ReactNode;
}

export function IOSNativeTabsRenderer(props: IOSNativeTabsProps) {
  return (
    <TabView selection={props.selectedTab} onSelectionChange={props.onSelectTab}>
      {props.children}
    </TabView>
  );
}

export const IOSRouterIntegratedTabs = integrateWithRouter(
  createStandardRouterNavigator(IOSNativeTabsRenderer)
);
`,
  });

  files.push({
    path: 'src/foundation/navigation/renderers/ios/NativeSplitView.ios.tsx',
    ownership: 'generated',
    content: `${GENERATED_HEADER}
import React from 'react';
import { NavigationSplitView } from '@expo/ui/swift-ui';

export function IOSNativeSplitViewRenderer(props: {
  sidebar: React.ReactNode;
  detail: React.ReactNode;
}) {
  return (
    <NavigationSplitView sidebar={props.sidebar} detail={props.detail} />
  );
}
`,
  });

  // 7. Android Jetpack Compose + Expo Router Renderers
  files.push({
    path: 'src/foundation/navigation/renderers/android/NativeStack.android.tsx',
    ownership: 'generated',
    content: `${GENERATED_HEADER}
import React from 'react';
import { Stack } from 'expo-router';
import { TopAppBar } from '@expo/ui/jetpack-compose';

export function AndroidNativeStackRenderer(props: { title?: string }) {
  return (
    <>
      <TopAppBar title={props.title ?? ''} />
      <Stack />
    </>
  );
}
`,
  });

  files.push({
    path: 'src/foundation/navigation/renderers/android/NativeTabs.android.tsx',
    ownership: 'generated',
    content: `${GENERATED_HEADER}
import React from 'react';
import { NavigationBar } from '@expo/ui/jetpack-compose';
import { NativeTabs } from 'expo-router/unstable-native-tabs';

export interface AndroidNativeTabsProps {
  selectedTab: string;
  onSelectTab: (tabId: string) => void;
  useFallback?: boolean;
  tabs: Array<{ id: string; label: string; icon: string }>;
  children?: React.ReactNode;
}

export function AndroidNativeTabsRenderer(props: AndroidNativeTabsProps) {
  if (props.useFallback) {
    return <NativeTabs>{props.children}</NativeTabs>;
  }
  return (
    <>
      {props.children}
      <NavigationBar
        selectedItem={props.selectedTab}
        onSelectItem={props.onSelectTab}
        items={props.tabs}
      />
    </>
  );
}
`,
  });

  files.push({
    path: 'src/foundation/navigation/renderers/android/NativeDrawer.android.tsx',
    ownership: 'generated',
    content: `${GENERATED_HEADER}
import React from 'react';
import { Drawer } from 'expo-router/drawer';

export function AndroidNativeDrawerRenderer() {
  return <Drawer />;
}
`,
  });

  // 8. Expo Router Route Adapter files in src/app/
  files.push({
    path: 'src/app/_layout.tsx',
    ownership: 'generated',
    content: `${GENERATED_HEADER}
import React from 'react';
import { Slot } from 'expo-router';

export default function RootFoundationLayout() {
  return <Slot />;
}
`,
  });

  files.push({
    path: 'src/app/(application)/_layout.tsx',
    ownership: 'generated',
    content: `${GENERATED_HEADER}
import React from 'react';
import { Slot } from 'expo-router';

export default function ApplicationGroupLayout() {
  return <Slot />;
}
`,
  });

  for (const route of Object.values(navIR.routes)) {
    const appFilePath = routeToAppFilePath(route);
    files.push({
      path: appFilePath,
      ownership: 'generated',
      content: `${GENERATED_HEADER}
import React from 'react';
import { useLocalSearchParams } from 'expo-router';
import { resolveScreenReference } from '../../foundation/navigation/RouteResolver';

/**
 * Route Adapter for route "${route.id}" (${route.path})
 * Resolves external Screen Reference "${route.screenRef}".
 */
export default function RouteAdapter_${route.id.replace(/[^a-zA-Z0-9_]/g, '_')}() {
  const params = useLocalSearchParams();
  const ScreenComponent = resolveScreenReference('${route.screenRef}');
  return <ScreenComponent routeId="${route.id}" params={params} />;
}
`,
    });
  }

  return files;
}
